/**
 * @file gameManager.ts
 * Variables globales du jeu
 *
 * Note : globalThis.game est mis à jour via setGameInstance() après
 * l'instanciation de Game dans index.html (window === globalThis en navigateur).
 */

import type { GameRuntime } from './src/types/game.js';

export let game: GameRuntime | null = null;

export let currentZone: number = 1;
// Reassigned from zoneSystem / saveSystem / combat via module binding (not in this file).
export let maxReachedZone: number = 1; // eslint-disable-line prefer-const -- cross-module zone state
export let currentRegion: string = 'kanto'; // eslint-disable-line prefer-const -- cross-module zone state
export let maxReachedZoneByRegion: Record<string, number> = { kanto: 1, johto: 0 }; // eslint-disable-line prefer-const -- cross-module zone state

function syncZoneGlobalsToGlobalThis(): void {
    if (typeof globalThis === 'undefined') return;
    globalThis.game = game;
    globalThis.currentZone = currentZone;
    globalThis.maxReachedZone = maxReachedZone;
    globalThis.currentRegion = currentRegion;
    globalThis.maxReachedZoneByRegion = maxReachedZoneByRegion;
}

export function setGameInstance(instance: GameRuntime): void {
    game = instance;
    syncZoneGlobalsToGlobalThis();
}

/** Zone active (globalThis synchronisé par zoneSystem au voyage). */
export function getActiveZoneId(): number {
    const fromModule = Number(currentZone);
    if (Number.isFinite(fromModule)) return fromModule;
    const fromGlobal = Number(globalThis.currentZone);
    if (Number.isFinite(fromGlobal)) return fromGlobal;
    return 1;
}

export function setActiveZone(zoneId: number): void {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return;
    currentZone = zId;
    if (typeof globalThis !== 'undefined') globalThis.currentZone = zId;
}

export function setMaxReachedZone(zoneId: number): void {
    const zId = Number(zoneId);
    if (!Number.isFinite(zId)) return;
    maxReachedZone = zId;
    if (typeof globalThis !== 'undefined') globalThis.maxReachedZone = zId;
}

export function setCurrentRegion(regionId: string): void {
    const rId = String(regionId || 'kanto');
    currentRegion = rId;
    if (typeof globalThis !== 'undefined') globalThis.currentRegion = rId;
}

/** Remplace le contenu de maxReachedZoneByRegion (binding module, pas réassignation cross-module). */
export function replaceMaxReachedZoneByRegion(next: Record<string, number>): void {
    for (const k of Object.keys(maxReachedZoneByRegion)) delete maxReachedZoneByRegion[k];
    Object.assign(maxReachedZoneByRegion, next);
    if (typeof globalThis !== 'undefined') globalThis.maxReachedZoneByRegion = maxReachedZoneByRegion;
}

/** @deprecated Alias — préférer laisser setActiveZone / setMaxReachedZone / replaceMaxReachedZoneByRegion synchroniser globalThis. */
export function syncZoneGlobalsToWindow(): void {
    syncZoneGlobalsToGlobalThis();
}

if (typeof globalThis !== 'undefined') {
    globalThis.setGameInstance = setGameInstance;
    syncZoneGlobalsToGlobalThis();
}
